t.script:
(function () {
  var root = document.getElementById('s'), key = root.getAttribute('data-k'), q = document.getElementById('q'), box = document.getElementById('box');
  var up = window.parent, here = location.origin, map = null, live = false, tok = null, timer = null, seq = 0;
  function say(m) { m.smb = 1; if (up !== window) { up.postMessage(m, here); } }
  function shut() { box.hidden = true; box.textContent = ''; }
  function tell() { var c = map.getCenter(); if (c) { say({ c: [c.lat(), c.lng()], z: map.getZoom() }); } }
  if (!key || up === window) { say({ off: 1 }); return; }
  window.gm_authFailure = function () { say({ off: 1 }); };
  window.smbG = function () {
    Promise.all([google.maps.importLibrary('maps'), google.maps.importLibrary('places')]).then(function () { say({ ready: 1 }); }, function () { say({ off: 1 }); });
  };
  window.addEventListener('message', function (e) {
    var m = e.data; if (e.origin !== here || e.source !== up || !m || m.smb !== 2 || !window.google) { return; }
    if (m.init && !map) {
      map = new google.maps.Map(document.getElementById('g'), { center: { lat: m.lat, lng: m.lng }, zoom: m.z, disableDefaultUI: true, zoomControl: true, gestureHandling: 'greedy', clickableIcons: false });
      map.addListener('center_changed', tell);
      map.addListener('zoom_changed', function () { tell(); if (live) { say({ t: 1 }); } });
      map.addListener('dragstart', function () { q.blur(); shut(); say({ t: 1 }); });
      map.addListener('click', function (ev) { shut(); say({ t: 1 }); map.panTo(ev.latLng); });
      map.addListener('idle', function () { live = true; tell(); });
    } else if (m.go && map) { live = false; map.setCenter({ lat: m.lat, lng: m.lng }); map.setZoom(m.z); }
  });
  function ask() {
    var v = q.value.trim(), mine = ++seq;
    if (!map || v.length < 3) { if (v.length < 3) { shut(); } return; }
    var P = google.maps.places;
    if (!tok) { tok = new P.AutocompleteSessionToken(); }
    P.AutocompleteSuggestion.fetchAutocompleteSuggestions({ input: v, sessionToken: tok, includedRegionCodes: ['lb'] }).then(function (r) {
      if (mine !== seq) { return; }
      box.textContent = '';
      var list = (r.suggestions || []).filter(function (s) { return s.placePrediction; }).slice(0, 5);
      list.forEach(function (s) {
        var p = s.placePrediction, b = document.createElement('button'), sm = document.createElement('small');
        b.type = 'button'; b.className = 'r';
        b.textContent = p.mainText ? p.mainText.text : p.text.text;
        sm.textContent = p.secondaryText ? p.secondaryText.text : ''; b.appendChild(sm);
        b.addEventListener('click', function () {
          q.value = p.text.text; q.blur(); shut();
          p.toPlace().fetchFields({ fields: ['location'] }).then(function (d) {
            tok = null;
            var l = d.place.location; if (l) { live = false; map.setCenter(l); map.setZoom(17); say({ t: 1, picked: 1 }); }
          }, function () { tok = null; });
        });
        box.appendChild(b);
      });
      if (!list.length) { var n = document.createElement('div'); n.className = 'n'; n.textContent = 'No match. Try another name, or move the map to your door.'; box.appendChild(n); }
      box.hidden = false;
    }, function () { if (mine === seq) { shut(); } });
  }
  q.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(ask, 350); });
  q.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); var f = box.querySelector('.r'); if (f) { f.click(); } } });
  var sc = document.createElement('script');
  sc.src = 'https://maps.googleapis.com/maps/api/js?key=' + encodeURIComponent(key) + '&loading=async&region=LB&callback=smbG';
  sc.onerror = function () { say({ off: 1 }); };
  document.head.appendChild(sc);
})();

(function () {
  var el = document.getElementById('map'); if (!el) { return; }
  var lat = parseFloat(el.getAttribute('data-lat')), lng = parseFloat(el.getAttribute('data-lng')), has = !isNaN(lat) && !isNaN(lng);
  var start = has ? [lat, lng, 17] : [33.89, 35.55, 9], moved = has, api = null;
  var good = document.getElementById('good'), bad = document.getElementById('bad'), save = document.getElementById('save'), me = document.getElementById('me'), hint = document.querySelector('.hint');
  var wait = 'The map is still loading. Please try again in a moment.';
  function fail(t) { bad.textContent = t; bad.hidden = false; }
  function touched() { moved = true; good.hidden = true; bad.hidden = true; }
  /* the free Leaflet / OpenStreetMap map: used when there is no Google key or Google does not answer */
  function leaf() {
    if (!window.L) { return; }
    el.hidden = false;
    var map = L.map(el, { zoomControl: true }).setView([start[0], start[1]], start[2]);
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap contributors' }).addTo(map);
    var pin = L.marker(map.getCenter(), { draggable: true }).addTo(map);
    map.on('move', function () { pin.setLatLng(map.getCenter()); });
    map.on('dragstart zoomstart', touched);
    pin.on('dragend', function () { touched(); map.panTo(pin.getLatLng()); });
    map.on('click', function (e) { touched(); map.panTo(e.latlng); });
    api = { center: function () { var c = map.getCenter(); return [c.lat, c.lng]; }, zoom: function () { return map.getZoom(); }, go: function (a, b, z) { map.setView([a, b], z); } };
  }
  /* 28 Nov 2026: the Google map and search run in the frame; it reports the map's centre and zoom to this page */
  var sf = document.getElementById('sf'), gw = document.getElementById('gw');
  if (!sf) { leaf(); } else {
    var gc = [start[0], start[1]], gz = start[2], ready = false, dead = false;
    var back = function () { if (dead) { return; } dead = true; api = null; gw.hidden = true; leaf(); };
    var late = setTimeout(function () { if (!ready) { back(); } }, 12000);
    window.addEventListener('message', function (e) {
      var m = e.data; if (dead || e.origin !== location.origin || e.source !== sf.contentWindow || !m || m.smb !== 1) { return; }
      if (m.off) { clearTimeout(late); back(); return; }
      if (m.ready && !ready) {
        ready = true; clearTimeout(late);
        sf.contentWindow.postMessage({ smb: 2, init: 1, lat: start[0], lng: start[1], z: start[2] }, location.origin);
        api = { center: function () { return gc; }, zoom: function () { return gz; }, go: function (a, b, z) { gc = [a, b]; gz = z; sf.contentWindow.postMessage({ smb: 2, go: 1, lat: a, lng: b, z: z }, location.origin); } };
      }
      if (m.c) { gc = m.c; gz = m.z; }
      if (m.t) { touched(); }
      if (m.picked && hint) { hint.textContent = 'Now move the map so the pin sits exactly on your door, then save.'; }
    });
  }
  /* 26 Nov 2026: say why the phone gave no position (blocked for the site, switched off, or too slow) and, when the
     precise fix fails, try once more with the quick network position before giving up */
  var why = { 1: 'Location is blocked for this site. Tap the lock icon next to the address bar, allow Location, then try again. Or drag the map to your door.',
              2: 'Your phone could not find its position. Turn on Location (GPS) and try again, or drag the map to your door.',
              3: 'Finding your position took too long. Try again, or drag the map to your door.' };
  function locate(precise) {
    navigator.geolocation.getCurrentPosition(function (p) { me.disabled = false; me.textContent = 'Use my current location'; touched(); if (api) { api.go(p.coords.latitude, p.coords.longitude, 18); } },
      function (e) { if (precise && e.code !== 1) { locate(false); return; } me.disabled = false; me.textContent = 'Use my current location'; fail(why[e.code] || why[2]); },
      precise ? { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 } : { enableHighAccuracy: false, timeout: 15000, maximumAge: 300000 });
  }
  me.addEventListener('click', function () {
    if (!api) { fail(wait); return; }
    if (!navigator.geolocation) { fail(why[2]); return; }
    me.disabled = true; me.textContent = 'Finding your location…'; bad.hidden = true; locate(true);
  });
  save.addEventListener('click', function () {
    if (!api) { fail(wait); return; }
    var c = api.center();
    if (!moved || api.zoom() < 15) { fail('Please zoom in and place the pin on your door first.'); return; }
    if (c[0] < 33.0 || c[0] > 34.75 || c[1] < 35.0 || c[1] > 36.7) { fail('We deliver in Lebanon only. Please place the pin in Lebanon.'); return; }
    var fd = new FormData();
    fd.append('csrf_token', el.getAttribute('data-c')); fd.append('x_name', 'pin'); fd.append('x_order', el.getAttribute('data-o')); fd.append('x_token', el.getAttribute('data-t'));
    fd.append('x_lat', c[0].toFixed(7)); fd.append('x_lng', c[1].toFixed(7));
    save.disabled = true; bad.hidden = true;
    fetch('/website/form/x_location_pin', { method: 'POST', body: fd })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j || !j.id) { throw new Error('no id'); } save.disabled = false; good.hidden = false; })
      .catch(function () { save.disabled = false; fail('Could not save. Please check your connection and try again.'); });
  });
})();
